\node[right,font=\small] at (E3) {$BR$};
\node[right,font=\small] at (E4) {$BB$};
\node[font=\small] at (2.2,3.2) {Draw $1$};
\node[font=\small] at (4.8,3.2) {Draw $2$};
\node[font=\small] at (6.1,3.2) {Outcome};
